    int cnt = 0;
    for (Map.Entry<String, String> entry : compoundConf) {
        cnt++;
        if (entry.getKey().equals("B"))
            assertEquals("2b", entry.getValue());
        else if (entry.getKey().equals("G"))
            assertEquals(null, entry.getValue());
