            assertEquals("Did not consume enough bytes.", I_LENGTHS[i], buf1.getPosition() - 1);
        }
    }
    /*
     * assert natural sort order is preserved by the codec.
     */
    for (Order ord : new Order[] { Order.ASCENDING, Order.DESCENDING }) {
