@Test
public void testScannerNextRPCTimesout() throws Exception {
    final TableName TABLE_NAME = TableName.valueOf("testScannerNextRPCTimesout");
    Table ht = TEST_UTIL.createTable(TABLE_NAME, FAMILY);
    byte[] r1 = Bytes.toBytes("row-1");
    byte[] r2 = Bytes.toBytes("row-2");
    byte[] r3 = Bytes.toBytes("row-3");
    putToTable(ht, r1);
    putToTable(ht, r2);
    putToTable(ht, r3);
    LOG.info("Wrote our three values");
    RSRpcServicesWithScanTimeout.seqNoToSleepOn = 1;
    Scan scan = new Scan();
    scan.setCaching(1);
    ResultScanner scanner = ht.getScanner(scan);
    Result result = scanner.next();
    assertTrue("Expected row: row-1", Bytes.equals(r1, result.getRow()));
    LOG.info("Got expected first row");
    long t1 = System.currentTimeMillis();
    result = scanner.next();
    assertTrue((System.currentTimeMillis() - t1) > rpcTimeout);
    assertTrue("Expected row: row-2", Bytes.equals(r2, result.getRow()));
    // No need of sleep
    RSRpcServicesWithScanTimeout.seqNoToSleepOn = -1;
    result = scanner.next();
    assertTrue("Expected row: row-3", Bytes.equals(r3, result.getRow()));
    scanner.close();
    // test the case that RPC is always timesout
    scanner = ht.getScanner(scan);
    RSRpcServicesWithScanTimeout.sleepAlways = true;
    RSRpcServicesWithScanTimeout.tryNumber = 0;
    try {
        result = scanner.next();
    } catch (IOException ioe) {
        // catch the exception after max retry number
        LOG.info("Failed after maximal attempts=" + CLIENT_RETRIES_NUMBER, ioe);
    }
    assertTrue("Expected maximal try number=" + CLIENT_RETRIES_NUMBER + ", actual =" + RSRpcServicesWithScanTimeout.tryNumber, RSRpcServicesWithScanTimeout.tryNumber <= CLIENT_RETRIES_NUMBER);
}

/**
 * Test that a client that fails an RPC to the master retries properly and
 * doesn't throw any unexpected exceptions.
 * @throws Exception
 */
@Test
public void testAdminTimeout() throws Exception {
    Connection lastConnection = null;
    boolean lastFailed = false;
    int initialInvocations = RandomTimeoutBlockingRpcChannel.invokations.get();
    RandomTimeoutRpcClient rpcClient = (RandomTimeoutRpcClient) RpcClientFactory.createClient(TEST_UTIL.getConfiguration(), TEST_UTIL.getClusterKey());
    try {
        for (int i = 0; i < 5 || (lastFailed && i < 100); ++i) {
            lastFailed = false;
            // Ensure the HBaseAdmin uses a new connection by changing Configuration.
            Configuration conf = HBaseConfiguration.create(TEST_UTIL.getConfiguration());
            conf.set(HConstants.HBASE_CLIENT_INSTANCE_ID, String.valueOf(-1));
            Admin admin = null;
            Connection connection = null;
            try {
                connection = ConnectionFactory.createConnection(conf);
                admin = connection.getAdmin();
                // run some admin commands
                HBaseAdmin.checkHBaseAvailable(conf);
                admin.setBalancerRunning(false, false);
            } catch (MasterNotRunningException ex) {
                // Since we are randomly throwing SocketTimeoutExceptions, it is possible to get
                // a MasterNotRunningException.  It's a bug if we get other exceptions.
                lastFailed = true;
            } finally {
                if (admin != null) {
                    admin.close();
                    if (admin.getConnection().isClosed()) {
                        rpcClient = (RandomTimeoutRpcClient) RpcClientFactory.createClient(TEST_UTIL.getConfiguration(), TEST_UTIL.getClusterKey());
                    }
                }
                if (connection != null) {
                    connection.close();
                }
            }
        }
        // Ensure the RandomTimeoutRpcEngine is actually being used.
        assertFalse(lastFailed);
        assertTrue(RandomTimeoutBlockingRpcChannel.invokations.get() > initialInvocations);
    } finally {
        rpcClient.close();
    }
}

