@Test
public void testScanLimitAndOffset() throws Exception {
    //byte [] TABLE = HTestConst.DEFAULT_TABLE_BYTES;
    byte[][] ROWS = HTestConst.makeNAscii(HTestConst.DEFAULT_ROW_BYTES, 2);
    byte[][] FAMILIES = HTestConst.makeNAscii(HTestConst.DEFAULT_CF_BYTES, 3);
    byte[][] QUALIFIERS = HTestConst.makeNAscii(HTestConst.DEFAULT_QUALIFIER_BYTES, 10);
    HTableDescriptor htd = new HTableDescriptor(TableName.valueOf(HTestConst.DEFAULT_TABLE_BYTES));
    HRegionInfo info = new HRegionInfo(HTestConst.DEFAULT_TABLE, null, null, false);
    for (byte[] family : FAMILIES) {
        HColumnDescriptor hcd = new HColumnDescriptor(family);
        htd.addFamily(hcd);
    }
    HRegion region = HBaseTestingUtility.createRegionAndWAL(info, TEST_UTIL.getDataTestDir(), TEST_UTIL.getConfiguration(), htd);
    try {
        Put put;
        Scan scan;
        Result result;
        boolean toLog = true;
        List<Cell> kvListExp = new ArrayList<Cell>();
        int storeOffset = 1;
        int storeLimit = 3;
        for (int r = 0; r < ROWS.length; r++) {
            put = new Put(ROWS[r]);
            for (int c = 0; c < FAMILIES.length; c++) {
                for (int q = 0; q < QUALIFIERS.length; q++) {
                    KeyValue kv = new KeyValue(ROWS[r], FAMILIES[c], QUALIFIERS[q], 1, HTestConst.DEFAULT_VALUE_BYTES);
                    put.add(kv);
                    if (storeOffset <= q && q < storeOffset + storeLimit) {
                        kvListExp.add(kv);
                    }
                }
            }
            region.put(put);
        }
        scan = new Scan();
        scan.setRowOffsetPerColumnFamily(storeOffset);
        scan.setMaxResultsPerColumnFamily(storeLimit);
        RegionScanner scanner = region.getScanner(scan);
        List<Cell> kvListScan = new ArrayList<Cell>();
        List<Cell> results = new ArrayList<Cell>();
        while (scanner.next(results) || !results.isEmpty()) {
            kvListScan.addAll(results);
            results.clear();
        }
        result = Result.create(kvListScan);
        TestScannersFromClientSide.verifyResult(result, kvListExp, toLog, "Testing scan with storeOffset and storeLimit");
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(region);
    }
}

@Test
public void testLeaseRenewal() throws Exception {
    HTable table = TEST_UTIL.createTable(TableName.valueOf("testLeaseRenewal"), FAMILY);
    Put p = new Put(ROW_BYTES);
    p.addColumn(FAMILY, COL_QUAL, VAL_BYTES);
    table.put(p);
    p = new Put(ANOTHERROW);
    p.addColumn(FAMILY, COL_QUAL, VAL_BYTES);
    table.put(p);
    Scan s = new Scan();
    s.setCaching(1);
    ResultScanner rs = table.getScanner(s);
    // make sure that calling renewLease does not impact the scan results
    assertTrue(rs.renewLease());
    assertTrue(Arrays.equals(rs.next().getRow(), ANOTHERROW));
    // renew the lease a few times, long enough to be sure
    // the lease would have expired otherwise
    Thread.sleep(leaseTimeout / 2);
    assertTrue(rs.renewLease());
    Thread.sleep(leaseTimeout / 2);
    assertTrue(rs.renewLease());
    Thread.sleep(leaseTimeout / 2);
    assertTrue(rs.renewLease());
    // make sure we haven't advanced the scanner
    assertTrue(Arrays.equals(rs.next().getRow(), ROW_BYTES));
    assertTrue(rs.renewLease());
    // make sure scanner is exhausted now
    assertNull(rs.next());
    // renewLease should return false now
    assertFalse(rs.renewLease());
    rs.close();
    table.close();
    MetricsHBaseServerSource serverSource = TEST_UTIL.getMiniHBaseCluster().getRegionServer(0).getRpcServer().getMetrics().getMetricsSource();
    HELPER.assertCounter("exceptions.OutOfOrderScannerNextException", 0, serverSource);
}

@Test
public void testPreserveMetaCacheOnException() throws Exception {
    ((FakeRSRpcServices) badRS.getRSRpcServices()).setExceptionInjector(new RoundRobinExceptionInjector());
    Configuration conf = new Configuration(TEST_UTIL.getConfiguration());
    conf.set("hbase.client.retries.number", "1");
    ConnectionImplementation conn = (ConnectionImplementation) ConnectionFactory.createConnection(conf);
    try {
        Table table = conn.getTable(TABLE_NAME);
        byte[] row = Bytes.toBytes("row1");
        Put put = new Put(row);
        put.addColumn(FAMILY, QUALIFIER, Bytes.toBytes(10));
        Get get = new Get(row);
        Append append = new Append(row);
        append.add(FAMILY, QUALIFIER, Bytes.toBytes(11));
        Increment increment = new Increment(row);
        increment.addColumn(FAMILY, QUALIFIER, 10);
        Delete delete = new Delete(row);
        delete.addColumn(FAMILY, QUALIFIER);
        RowMutations mutations = new RowMutations(row);
        mutations.add(put);
        mutations.add(delete);
        Exception exp;
        boolean success;
        for (int i = 0; i < 50; i++) {
            exp = null;
            success = false;
            try {
                table.put(put);
                // If at least one operation succeeded, we should have cached the region location.
                success = true;
                table.get(get);
                table.append(append);
                table.increment(increment);
                table.delete(delete);
                table.mutateRow(mutations);
            } catch (IOException ex) {
                // Only keep track of the last exception that updated the meta cache
                if (ClientExceptionsUtil.isMetaClearingException(ex) || success) {
                    exp = ex;
                }
            }
            // Do not test if we did not touch the meta cache in this iteration.
            if (exp != null && ClientExceptionsUtil.isMetaClearingException(exp)) {
                assertNull(conn.getCachedLocation(TABLE_NAME, row));
            } else if (success) {
                assertNotNull(conn.getCachedLocation(TABLE_NAME, row));
            }
        }
    } finally {
        conn.close();
    }
}

