public void testRanges() throws IOException {
    byte[] key1Start = new byte[] { -3 };
    byte[] key1End = new byte[] { -2 };
    byte[] key2Start = new byte[] { 5 };
    byte[] key2End = new byte[] { 6 };
    byte[] badKey = new byte[] { -10 };
