@Test
public void testPrefixScanning() throws IOException {
    TableName tableName = TableName.valueOf("prefixScanning");
    createTable(tableName, "F");
    Table table = openTable(tableName);
    /**
     * Note that about half of these tests were relevant for an different implementation approach
     * of setRowPrefixFilter. These test cases have been retained to ensure that also the
     * edge cases found there are still covered.
     */
    final byte[][] rowIds = { //  0
    { (byte) 0x11 }, //  1
    { (byte) 0x12 }, //  2
    { (byte) 0x12, (byte) 0x23, (byte) 0xFF, (byte) 0xFE }, //  3
    { (byte) 0x12, (byte) 0x23, (byte) 0xFF, (byte) 0xFF }, //  4
    { (byte) 0x12, (byte) 0x23, (byte) 0xFF, (byte) 0xFF, (byte) 0x00 }, //  5
    { (byte) 0x12, (byte) 0x23, (byte) 0xFF, (byte) 0xFF, (byte) 0x01 }, //  6
    { (byte) 0x12, (byte) 0x24 }, //  7
    { (byte) 0x12, (byte) 0x24, (byte) 0x00 }, //  8
    { (byte) 0x12, (byte) 0x24, (byte) 0x00, (byte) 0x00 }, //  9
    { (byte) 0x12, (byte) 0x25 }, // 10
    { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF } };
    for (byte[] rowId : rowIds) {
        Put p = new Put(rowId);
        // Use the rowId as the column qualifier
        p.addColumn("F".getBytes(), rowId, "Dummy value".getBytes());
        table.put(p);
    }
    byte[] prefix0 = {};
    List<byte[]> expected0 = new ArrayList<>(16);
    // Expect all rows
    expected0.addAll(Arrays.asList(rowIds));
    byte[] prefix1 = { (byte) 0x12, (byte) 0x23 };
    List<byte[]> expected1 = new ArrayList<>(16);
    expected1.add(rowIds[2]);
    expected1.add(rowIds[3]);
    expected1.add(rowIds[4]);
    expected1.add(rowIds[5]);
    byte[] prefix2 = { (byte) 0x12, (byte) 0x23, (byte) 0xFF, (byte) 0xFF };
    List<byte[]> expected2 = new ArrayList<>();
    expected2.add(rowIds[3]);
    expected2.add(rowIds[4]);
    expected2.add(rowIds[5]);
    byte[] prefix3 = { (byte) 0x12, (byte) 0x24 };
    List<byte[]> expected3 = new ArrayList<>();
    expected3.add(rowIds[6]);
    expected3.add(rowIds[7]);
    expected3.add(rowIds[8]);
    byte[] prefix4 = { (byte) 0xFF, (byte) 0xFF };
    List<byte[]> expected4 = new ArrayList<>();
    expected4.add(rowIds[10]);
    // ========
    // PREFIX 0
    Scan scan = new Scan();
    scan.setRowPrefixFilter(prefix0);
    verifyScanResult(table, scan, expected0, "Scan empty prefix failed");
    // ========
    // PREFIX 1
    scan = new Scan();
    scan.setRowPrefixFilter(prefix1);
    verifyScanResult(table, scan, expected1, "Scan normal prefix failed");
    scan.setRowPrefixFilter(null);
    verifyScanResult(table, scan, expected0, "Scan after prefix reset failed");
    scan = new Scan();
    scan.setFilter(new ColumnPrefixFilter(prefix1));
    verifyScanResult(table, scan, expected1, "Double check on column prefix failed");
    // ========
    // PREFIX 2
    scan = new Scan();
    scan.setRowPrefixFilter(prefix2);
    verifyScanResult(table, scan, expected2, "Scan edge 0xFF prefix failed");
    scan.setRowPrefixFilter(null);
    verifyScanResult(table, scan, expected0, "Scan after prefix reset failed");
    scan = new Scan();
    scan.setFilter(new ColumnPrefixFilter(prefix2));
    verifyScanResult(table, scan, expected2, "Double check on column prefix failed");
    // ========
    // PREFIX 3
    scan = new Scan();
    scan.setRowPrefixFilter(prefix3);
    verifyScanResult(table, scan, expected3, "Scan normal with 0x00 ends failed");
    scan.setRowPrefixFilter(null);
    verifyScanResult(table, scan, expected0, "Scan after prefix reset failed");
    scan = new Scan();
    scan.setFilter(new ColumnPrefixFilter(prefix3));
    verifyScanResult(table, scan, expected3, "Double check on column prefix failed");
    // ========
    // PREFIX 4
    scan = new Scan();
    scan.setRowPrefixFilter(prefix4);
    verifyScanResult(table, scan, expected4, "Scan end prefix failed");
    scan.setRowPrefixFilter(null);
    verifyScanResult(table, scan, expected0, "Scan after prefix reset failed");
    scan = new Scan();
    scan.setFilter(new ColumnPrefixFilter(prefix4));
    verifyScanResult(table, scan, expected4, "Double check on column prefix failed");
    // ========
    // COMBINED
    // Prefix + Filter
    scan = new Scan();
    scan.setRowPrefixFilter(prefix1);
    verifyScanResult(table, scan, expected1, "Prefix filter failed");
    scan.setFilter(new ColumnPrefixFilter(prefix2));
    verifyScanResult(table, scan, expected2, "Combined Prefix + Filter failed");
    scan.setRowPrefixFilter(null);
    verifyScanResult(table, scan, expected2, "Combined Prefix + Filter; removing Prefix failed");
    scan.setFilter(null);
    verifyScanResult(table, scan, expected0, "Scan after Filter reset failed");
    // ========
    // Reversed: Filter + Prefix
    scan = new Scan();
    scan.setFilter(new ColumnPrefixFilter(prefix2));
    verifyScanResult(table, scan, expected2, "Test filter failed");
    scan.setRowPrefixFilter(prefix1);
    verifyScanResult(table, scan, expected2, "Combined Filter + Prefix failed");
    scan.setFilter(null);
    verifyScanResult(table, scan, expected1, "Combined Filter + Prefix ; removing Filter failed");
    scan.setRowPrefixFilter(null);
    verifyScanResult(table, scan, expected0, "Scan after prefix reset failed");
}

/**
 * Test the overridden functionality of filterKeyValue(KeyValue)
 * @throws Exception
 */
@Test
public void testFilterKeyValue() throws Exception {
    Filter filter = new SingleColumnValueExcludeFilter(COLUMN_FAMILY, COLUMN_QUALIFIER, CompareOp.EQUAL, VAL_1);
    // A 'match' situation
    List<Cell> kvs = new ArrayList<Cell>();
    KeyValue kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER_2, VAL_1);
    kvs.add(new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER_2, VAL_1));
    kvs.add(new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER, VAL_1));
    kvs.add(new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER_2, VAL_1));
    filter.filterRowCells(kvs);
    assertEquals("resultSize", kvs.size(), 2);
    assertTrue("leftKV1", CellComparator.COMPARATOR.compare(kvs.get(0), kv) == 0);
    assertTrue("leftKV2", CellComparator.COMPARATOR.compare(kvs.get(1), kv) == 0);
    assertFalse("allRemainingWhenMatch", filter.filterAllRemaining());
    // A 'mismatch' situation
    filter.reset();
    // INCLUDE expected because test column has not yet passed
    kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER_2, VAL_1);
    assertTrue("otherColumn", filter.filterKeyValue(kv) == Filter.ReturnCode.INCLUDE);
    // Test column will pass (wont match), expect NEXT_ROW
    kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER, VAL_2);
    assertTrue("testedMismatch", filter.filterKeyValue(kv) == Filter.ReturnCode.NEXT_ROW);
    // After a mismatch (at least with LatestVersionOnly), subsequent columns are EXCLUDE
    kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER_2, VAL_1);
    assertTrue("otherColumn", filter.filterKeyValue(kv) == Filter.ReturnCode.NEXT_ROW);
}

@Test
public void testLongComparator() throws IOException {
    Filter filter = new SingleColumnValueFilter(COLUMN_FAMILY, COLUMN_QUALIFIER, CompareOp.GREATER, new LongComparator(100L));
    KeyValue kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER, Bytes.toBytes(1L));
    assertTrue("less than", filter.filterKeyValue(kv) == Filter.ReturnCode.NEXT_ROW);
    filter.reset();
    byte[] buffer = kv.getBuffer();
    Cell c = new ByteBufferedCellImpl(ByteBuffer.wrap(buffer), 0, buffer.length);
    assertTrue("less than", filter.filterKeyValue(c) == Filter.ReturnCode.NEXT_ROW);
    filter.reset();
    kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER, Bytes.toBytes(100L));
    assertTrue("Equals 100", filter.filterKeyValue(kv) == Filter.ReturnCode.NEXT_ROW);
    filter.reset();
    buffer = kv.getBuffer();
    c = new ByteBufferedCellImpl(ByteBuffer.wrap(buffer), 0, buffer.length);
    assertTrue("Equals 100", filter.filterKeyValue(c) == Filter.ReturnCode.NEXT_ROW);
    filter.reset();
    kv = new KeyValue(ROW, COLUMN_FAMILY, COLUMN_QUALIFIER, Bytes.toBytes(120L));
    assertTrue("include 120", filter.filterKeyValue(kv) == Filter.ReturnCode.INCLUDE);
    filter.reset();
    buffer = kv.getBuffer();
    c = new ByteBufferedCellImpl(ByteBuffer.wrap(buffer), 0, buffer.length);
    assertTrue("include 120", filter.filterKeyValue(c) == Filter.ReturnCode.INCLUDE);
}

