    HELPER.assertCounter("processCallTime_NumOps", 1, serverSource);
    HELPER.assertCounter("totalCallTime_NumOps", 1, serverSource);
    mrpc.sentBytes(103);
    mrpc.sentBytes(103);
    mrpc.sentBytes(103);
    mrpc.receivedBytes(104);
    mrpc.receivedBytes(104);
