/**
 * Cluster test which starts a region server with a region, then
 * removes the data from HDFS underneath it, and ensures that
 * errors are bubbled to the client.
 */
@Test(timeout = 5 * 60 * 1000)
public void testFullSystemBubblesFSErrors() throws Exception {
    // We won't have an error if the datanode is not there if we use short circuit
    //  it's a known 'feature'.
    Assume.assumeTrue(!util.isReadShortCircuitOn());
    try {
        // Make it fail faster.
        util.getConfiguration().setInt(HConstants.HBASE_CLIENT_RETRIES_NUMBER, 1);
        util.getConfiguration().setInt("hbase.lease.recovery.timeout", 10000);
        util.getConfiguration().setInt("hbase.lease.recovery.dfs.timeout", 1000);
        util.startMiniCluster(1);
        TableName tableName = TableName.valueOf("table");
        byte[] fam = Bytes.toBytes("fam");
        Admin admin = util.getHBaseAdmin();
        HTableDescriptor desc = new HTableDescriptor(tableName);
        desc.addFamily(new HColumnDescriptor(fam).setMaxVersions(1).setBlockCacheEnabled(false));
        admin.createTable(desc);
        // Make a new Configuration so it makes a new connection that has the
        // above configuration on it; else we use the old one w/ 10 as default.
        try (Table table = util.getConnection().getTable(tableName)) {
            // Load some data
            util.loadTable(table, fam, false);
            util.flush();
            util.countRows(table);
            // Kill the DFS cluster
            util.getDFSCluster().shutdownDataNodes();
            try {
                util.countRows(table);
                fail("Did not fail to count after removing data");
            } catch (Exception e) {
                LOG.info("Got expected error", e);
                assertTrue(e.getMessage().contains("Could not seek"));
            }
        }
        // Restart data nodes so that HBase can shut down cleanly.
        util.getDFSCluster().restartDataNodes();
    } finally {
        MiniHBaseCluster cluster = util.getMiniHBaseCluster();
        if (cluster != null)
            cluster.killAll();
        util.shutdownMiniCluster();
    }
}

@Test
public void testUsingMetaAndBinary() throws IOException {
    FileSystem filesystem = FileSystem.get(conf);
    Path rootdir = UTIL.getDataTestDirOnTestFS();
    // Up flush size else we bind up when we use default catalog flush of 16k.
    UTIL.getMetaTableDescriptor().setMemStoreFlushSize(64 * 1024 * 1024);
    Region mr = HBaseTestingUtility.createRegionAndWAL(HRegionInfo.FIRST_META_REGIONINFO, rootdir, this.conf, UTIL.getMetaTableDescriptor());
    try {
        // Write rows for three tables 'A', 'B', and 'C'.
        for (char c = 'A'; c < 'D'; c++) {
            HTableDescriptor htd = new HTableDescriptor(TableName.valueOf("" + c));
            final int last = 128;
            final int interval = 2;
            for (int i = 0; i <= last; i += interval) {
                HRegionInfo hri = new HRegionInfo(htd.getTableName(), i == 0 ? HConstants.EMPTY_BYTE_ARRAY : Bytes.toBytes((byte) i), i == last ? HConstants.EMPTY_BYTE_ARRAY : Bytes.toBytes((byte) i + interval));
                Put put = MetaTableAccessor.makePutFromRegionInfo(hri);
                put.setDurability(Durability.SKIP_WAL);
                mr.put(put);
            }
        }
        InternalScanner s = mr.getScanner(new Scan());
        try {
            List<Cell> keys = new ArrayList<Cell>();
            while (s.next(keys)) {
                LOG.info(keys);
                keys.clear();
            }
        } finally {
            s.close();
        }
        findRow(mr, 'C', 44, 44);
        findRow(mr, 'C', 45, 44);
        findRow(mr, 'C', 46, 46);
        findRow(mr, 'C', 43, 42);
        mr.flush(true);
        findRow(mr, 'C', 44, 44);
        findRow(mr, 'C', 45, 44);
        findRow(mr, 'C', 46, 46);
        findRow(mr, 'C', 43, 42);
        // Now delete 'C' and make sure I don't get entries from 'B'.
        byte[] firstRowInC = HRegionInfo.createRegionName(TableName.valueOf("" + 'C'), HConstants.EMPTY_BYTE_ARRAY, HConstants.ZEROES, false);
        Scan scan = new Scan(firstRowInC);
        s = mr.getScanner(scan);
        try {
            List<Cell> keys = new ArrayList<Cell>();
            while (s.next(keys)) {
                mr.delete(new Delete(CellUtil.cloneRow(keys.get(0))));
                keys.clear();
            }
        } finally {
            s.close();
        }
        // Assert we get null back (pass -1).
        findRow(mr, 'C', 44, -1);
        findRow(mr, 'C', 45, -1);
        findRow(mr, 'C', 46, -1);
        findRow(mr, 'C', 43, -1);
        mr.flush(true);
        findRow(mr, 'C', 44, -1);
        findRow(mr, 'C', 45, -1);
        findRow(mr, 'C', 46, -1);
        findRow(mr, 'C', 43, -1);
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(mr);
    }
}

/**
 * Test file of multiple deletes and with deletes as final key.
 * @see <a href="https://issues.apache.org/jira/browse/HBASE-751">HBASE-751</a>
 */
@Test
public void testGetClosestRowBefore3() throws IOException {
    Region region = null;
    byte[] c0 = UTIL.COLUMNS[0];
    byte[] c1 = UTIL.COLUMNS[1];
    try {
        TableName tn = TableName.valueOf(testName.getMethodName());
        HTableDescriptor htd = UTIL.createTableDescriptor(tn);
        region = UTIL.createLocalHRegion(htd, null, null);
        Put p = new Put(T00);
        p.addColumn(c0, c0, T00);
        region.put(p);
        p = new Put(T10);
        p.addColumn(c0, c0, T10);
        region.put(p);
        p = new Put(T20);
        p.addColumn(c0, c0, T20);
        region.put(p);
        Result r = UTIL.getClosestRowBefore(region, T20, c0);
        assertTrue(Bytes.equals(T20, r.getRow()));
        Delete d = new Delete(T20);
        d.addColumn(c0, c0);
        region.delete(d);
        r = UTIL.getClosestRowBefore(region, T20, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        p = new Put(T30);
        p.addColumn(c0, c0, T30);
        region.put(p);
        r = UTIL.getClosestRowBefore(region, T30, c0);
        assertTrue(Bytes.equals(T30, r.getRow()));
        d = new Delete(T30);
        d.addColumn(c0, c0);
        region.delete(d);
        r = UTIL.getClosestRowBefore(region, T30, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        r = UTIL.getClosestRowBefore(region, T31, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        region.flush(true);
        // try finding "010" after flush
        r = UTIL.getClosestRowBefore(region, T30, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        r = UTIL.getClosestRowBefore(region, T31, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        // Put into a different column family.  Should make it so I still get t10
        p = new Put(T20);
        p.addColumn(c1, c1, T20);
        region.put(p);
        r = UTIL.getClosestRowBefore(region, T30, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        r = UTIL.getClosestRowBefore(region, T31, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        region.flush(true);
        r = UTIL.getClosestRowBefore(region, T30, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        r = UTIL.getClosestRowBefore(region, T31, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        // Now try combo of memcache and mapfiles.  Delete the t20 COLUMS[1]
        // in memory; make sure we get back t10 again.
        d = new Delete(T20);
        d.addColumn(c1, c1);
        region.delete(d);
        r = UTIL.getClosestRowBefore(region, T30, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        // Ask for a value off the end of the file.  Should return t10.
        r = UTIL.getClosestRowBefore(region, T31, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        region.flush(true);
        r = UTIL.getClosestRowBefore(region, T31, c0);
        assertTrue(Bytes.equals(T10, r.getRow()));
        // Ok.  Let the candidate come out of hfile but have delete of
        // the candidate be in memory.
        p = new Put(T11);
        p.addColumn(c0, c0, T11);
        region.put(p);
        d = new Delete(T10);
        d.addColumn(c1, c1);
        r = UTIL.getClosestRowBefore(region, T12, c0);
        assertTrue(Bytes.equals(T11, r.getRow()));
    } finally {
        if (region != null) {
            try {
                WAL wal = ((HRegion) region).getWAL();
                ((HRegion) region).close();
                wal.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}

