        put.addColumn(fam2, (byte[]) null, ts, null);
        put.addColumn(fam3, (byte[]) null, ts, null);
        put.addColumn(fam4, (byte[]) null, ts, null);
        region.put(put);
        Scan scan = new Scan();
        scan.addFamily(fam2);
        scan.addFamily(fam4);
