/**
 * Verify behavior of getClosestBefore(...)
 */
@Test
public void testGetClosestBefore() throws Exception {
    HTableDescriptor htd = hbu.createTableDescriptor(name.getMethodName(), 1, 1000, 1, KeepDeletedCells.FALSE);
    Region region = hbu.createLocalHRegion(htd, null, null);
    try {
        // 2s in the past
        long ts = EnvironmentEdgeManager.currentTime() - 2000;
        Put p = new Put(T1, ts);
        p.addColumn(c0, c0, T1);
        region.put(p);
        p = new Put(T1, ts + 1);
        p.addColumn(c0, c0, T4);
        region.put(p);
        p = new Put(T3, ts);
        p.addColumn(c0, c0, T3);
        region.put(p);
        // now make sure that getClosestBefore(...) get can
        // rows that would be expired without minVersion.
        // also make sure it gets the latest version
        Result r = hbu.getClosestRowBefore(region, T1, c0);
        checkResult(r, c0, T4);
        r = hbu.getClosestRowBefore(region, T2, c0);
        checkResult(r, c0, T4);
        // now flush/compact
        region.flush(true);
        region.compact(true);
        r = hbu.getClosestRowBefore(region, T1, c0);
        checkResult(r, c0, T4);
        r = hbu.getClosestRowBefore(region, T2, c0);
        checkResult(r, c0, T4);
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(region);
    }
}

/**
 * Test mixed memstore and storefile scanning
 * with minimum versions.
 */
@Test
public void testStoreMemStore() throws Exception {
    // keep 3 versions minimum
    HTableDescriptor htd = hbu.createTableDescriptor(name.getMethodName(), 3, 1000, 1, KeepDeletedCells.FALSE);
    Region region = hbu.createLocalHRegion(htd, null, null);
    // 2s in the past
    long ts = EnvironmentEdgeManager.currentTime() - 2000;
    try {
        Put p = new Put(T1, ts - 1);
        p.addColumn(c0, c0, T2);
        region.put(p);
        p = new Put(T1, ts - 3);
        p.addColumn(c0, c0, T0);
        region.put(p);
        // now flush/compact
        region.flush(true);
        region.compact(true);
        p = new Put(T1, ts);
        p.addColumn(c0, c0, T3);
        region.put(p);
        p = new Put(T1, ts - 2);
        p.addColumn(c0, c0, T1);
        region.put(p);
        p = new Put(T1, ts - 3);
        p.addColumn(c0, c0, T0);
        region.put(p);
        // newest version in the memstore
        // the 2nd oldest in the store file
        // and the 3rd, 4th oldest also in the memstore
        Get g = new Get(T1);
        g.setMaxVersions();
        // this'll use ScanWildcardColumnTracker
        Result r = region.get(g);
        checkResult(r, c0, T3, T2, T1);
        g = new Get(T1);
        g.setMaxVersions();
        g.addColumn(c0, c0);
        // this'll use ExplicitColumnTracker
        r = region.get(g);
        checkResult(r, c0, T3, T2, T1);
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(region);
    }
}

