/**
 * Make sure the memstor behaves correctly with minimum versions
 */
@Test
public void testMemStore() throws Exception {
    HTableDescriptor htd = hbu.createTableDescriptor(name.getMethodName(), 2, 1000, 1, KeepDeletedCells.FALSE);
    Region region = hbu.createLocalHRegion(htd, null, null);
    // 2s in the past
    long ts = EnvironmentEdgeManager.currentTime() - 2000;
    try {
        // 2nd version
        Put p = new Put(T1, ts - 2);
        p.addColumn(c0, c0, T2);
        region.put(p);
        // 3rd version
        p = new Put(T1, ts - 1);
        p.addColumn(c0, c0, T3);
        region.put(p);
        // 4th version
        p = new Put(T1, ts);
        p.addColumn(c0, c0, T4);
        region.put(p);
        // now flush/compact
        region.flush(true);
        region.compact(true);
        // now put the first version (backdated)
        p = new Put(T1, ts - 3);
        p.addColumn(c0, c0, T1);
        region.put(p);
        // now the latest change is in the memstore,
        // but it is not the latest version
        Result r = region.get(new Get(T1));
        checkResult(r, c0, T4);
        Get g = new Get(T1);
        g.setMaxVersions();
        // this'll use ScanWildcardColumnTracker
        r = region.get(g);
        checkResult(r, c0, T4, T3);
        g = new Get(T1);
        g.setMaxVersions();
        g.addColumn(c0, c0);
        // this'll use ExplicitColumnTracker
        r = region.get(g);
        checkResult(r, c0, T4, T3);
        p = new Put(T1, ts + 1);
        p.addColumn(c0, c0, T5);
        region.put(p);
        // now the latest version is in the memstore
        g = new Get(T1);
        g.setMaxVersions();
        // this'll use ScanWildcardColumnTracker
        r = region.get(g);
        checkResult(r, c0, T5, T4);
        g = new Get(T1);
        g.setMaxVersions();
        g.addColumn(c0, c0);
        // this'll use ExplicitColumnTracker
        r = region.get(g);
        checkResult(r, c0, T5, T4);
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(region);
    }
}

/**
 * Verify basic minimum versions functionality
 */
@Test
public void testBaseCase() throws Exception {
    // 1 version minimum, 1000 versions maximum, ttl = 1s
    HTableDescriptor htd = hbu.createTableDescriptor(name.getMethodName(), 2, 1000, 1, KeepDeletedCells.FALSE);
    Region region = hbu.createLocalHRegion(htd, null, null);
    try {
        // 2s in the past
        long ts = EnvironmentEdgeManager.currentTime() - 2000;
        // 1st version
        Put p = new Put(T1, ts - 3);
        p.addColumn(c0, c0, T1);
        region.put(p);
        // 2nd version
        p = new Put(T1, ts - 2);
        p.addColumn(c0, c0, T2);
        region.put(p);
        // 3rd version
        p = new Put(T1, ts - 1);
        p.addColumn(c0, c0, T3);
        region.put(p);
        // 4th version
        p = new Put(T1, ts);
        p.addColumn(c0, c0, T4);
        region.put(p);
        Result r = region.get(new Get(T1));
        checkResult(r, c0, T4);
        Get g = new Get(T1);
        g.setTimeRange(0L, ts + 1);
        r = region.get(g);
        checkResult(r, c0, T4);
        // oldest version still exists
        g.setTimeRange(0L, ts - 2);
        r = region.get(g);
        checkResult(r, c0, T1);
        // gets see only available versions
        // even before compactions
        g = new Get(T1);
        g.setMaxVersions();
        // this'll use ScanWildcardColumnTracker
        r = region.get(g);
        checkResult(r, c0, T4, T3);
        g = new Get(T1);
        g.setMaxVersions();
        g.addColumn(c0, c0);
        // this'll use ExplicitColumnTracker
        r = region.get(g);
        checkResult(r, c0, T4, T3);
        // now flush
        region.flush(true);
        // with HBASE-4241 a flush will eliminate the expired rows
        g = new Get(T1);
        g.setTimeRange(0L, ts - 2);
        r = region.get(g);
        assertTrue(r.isEmpty());
        // major compaction
        region.compact(true);
        // after compaction the 4th version is still available
        g = new Get(T1);
        g.setTimeRange(0L, ts + 1);
        r = region.get(g);
        checkResult(r, c0, T4);
        // so is the 3rd
        g.setTimeRange(0L, ts);
        r = region.get(g);
        checkResult(r, c0, T3);
        // but the 2nd and earlier versions are gone
        g.setTimeRange(0L, ts - 1);
        r = region.get(g);
        assertTrue(r.isEmpty());
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(region);
    }
}

