    for (Pair<HRegionInfo, ServerName> p : initialRegionToServers) {
        initialRegions.add(p.getFirst());
    }
    List<HRegionInfo> currentRegions = new ArrayList<HRegionInfo>();
    for (Pair<HRegionInfo, ServerName> p : currentRegionToServers) {
        currentRegions.add(p.getFirst());
    }
    //this is the first region
    assertTrue(initialRegions.contains(mergedRegions.getFirst()));
    assertTrue(initialRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getFirst(), //this is the replica of the first region
    1)));
    //this is the second region
    assertTrue(initialRegions.contains(mergedRegions.getSecond()));
    assertTrue(initialRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getSecond(), //this is the replica of the second region
    1)));
    //this is the new region
    assertTrue(!initialRegions.contains(currentRegions.get(0)));
    assertTrue(!initialRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(currentRegions.get(0), //replica of the new region
    1)));
    assertTrue(currentRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(currentRegions.get(0), //replica of the new region
    1)));
    assertTrue(!currentRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getFirst(), //replica of the merged region
    1)));
    assertTrue(!currentRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getSecond(), //replica of the merged region
    1)));
}

