@Test
public void testMoveRegion() throws IOException, InterruptedException {
    String tableNameString = "testMoveRegion";
    TableName tableName = TableName.valueOf(tableNameString);
    Table t = TEST_UTIL.createTable(tableName, Bytes.toBytes("D"));
    TEST_UTIL.waitUntilAllRegionsAssigned(t.getName());
    Admin admin = TEST_UTIL.getHBaseAdmin();
    HRegionInfo regionInfo;
    byte[] row = Bytes.toBytes("r1");
    for (int i = 0; i < 30; i++) {
        boolean moved = false;
        try (RegionLocator locator = TEST_UTIL.getConnection().getRegionLocator(tableName)) {
            regionInfo = locator.getRegionLocation(row, true).getRegionInfo();
        }
        int currentServerIdx = cluster.getServerWith(regionInfo.getRegionName());
        int destServerIdx = (currentServerIdx + 1) % cluster.getLiveRegionServerThreads().size();
        HRegionServer currentServer = cluster.getRegionServer(currentServerIdx);
        HRegionServer destServer = cluster.getRegionServer(destServerIdx);
        byte[] destServerName = Bytes.toBytes(destServer.getServerName().getServerName());
        // Do a put. The counters should be non-zero now
        Put p = new Put(row);
        p.addColumn(Bytes.toBytes("D"), Bytes.toBytes("Zero"), Bytes.toBytes("VALUE"));
        t.put(p);
        MetricsRegionAggregateSource currentAgg = currentServer.getRegion(regionInfo.getRegionName()).getMetrics().getSource().getAggregateSource();
        String prefix = "namespace_" + NamespaceDescriptor.DEFAULT_NAMESPACE_NAME_STR + "_table_" + tableNameString + "_region_" + regionInfo.getEncodedName() + "_metric";
        metricsHelper.assertCounter(prefix + "_mutateCount", 1, currentAgg);
        try {
            admin.move(regionInfo.getEncodedNameAsBytes(), destServerName);
            moved = true;
            Thread.sleep(5000);
        } catch (IOException ioe) {
            moved = false;
        }
        TEST_UTIL.waitUntilAllRegionsAssigned(t.getName());
        if (moved) {
            MetricsRegionAggregateSource destAgg = destServer.getRegion(regionInfo.getRegionName()).getMetrics().getSource().getAggregateSource();
            metricsHelper.assertCounter(prefix + "_mutateCount", 0, destAgg);
        }
    }
    TEST_UTIL.deleteTable(tableName);
}

@Test
public void testResettingCounters() throws Exception {
    HBaseTestingUtility htu = new HBaseTestingUtility();
    Configuration conf = htu.getConfiguration();
    FileSystem fs = FileSystem.get(conf);
    byte[] table = Bytes.toBytes("table");
    byte[][] families = new byte[][] { Bytes.toBytes("family1"), Bytes.toBytes("family2"), Bytes.toBytes("family3") };
    int numQualifiers = 10;
    byte[][] qualifiers = new byte[numQualifiers][];
    for (int i = 0; i < numQualifiers; i++) qualifiers[i] = Bytes.toBytes("qf" + i);
    int numRows = 10;
    byte[][] rows = new byte[numRows][];
    for (int i = 0; i < numRows; i++) rows[i] = Bytes.toBytes("r" + i);
    HTableDescriptor htd = new HTableDescriptor(TableName.valueOf(table));
    for (byte[] family : families) htd.addFamily(new HColumnDescriptor(family));
    HRegionInfo hri = new HRegionInfo(htd.getTableName(), null, null, false);
    String testDir = htu.getDataTestDir() + "/TestResettingCounters/";
    Path path = new Path(testDir);
    if (fs.exists(path)) {
        if (!fs.delete(path, true)) {
            throw new IOException("Failed delete of " + path);
        }
    }
    Region region = HBaseTestingUtility.createRegionAndWAL(hri, path, conf, htd);
    try {
        Increment odd = new Increment(rows[0]);
        odd.setDurability(Durability.SKIP_WAL);
        Increment even = new Increment(rows[0]);
        even.setDurability(Durability.SKIP_WAL);
        Increment all = new Increment(rows[0]);
        all.setDurability(Durability.SKIP_WAL);
        for (int i = 0; i < numQualifiers; i++) {
            if (i % 2 == 0)
                even.addColumn(families[0], qualifiers[i], 1);
            else
                odd.addColumn(families[0], qualifiers[i], 1);
            all.addColumn(families[0], qualifiers[i], 1);
        }
        // increment odd qualifiers 5 times and flush
        for (int i = 0; i < 5; i++) region.increment(odd, HConstants.NO_NONCE, HConstants.NO_NONCE);
        region.flush(true);
        // increment even qualifiers 5 times
        for (int i = 0; i < 5; i++) region.increment(even, HConstants.NO_NONCE, HConstants.NO_NONCE);
        // increment all qualifiers, should have value=6 for all
        Result result = region.increment(all, HConstants.NO_NONCE, HConstants.NO_NONCE);
        assertEquals(numQualifiers, result.size());
        Cell[] kvs = result.rawCells();
        for (int i = 0; i < kvs.length; i++) {
            System.out.println(kvs[i].toString());
            assertTrue(CellUtil.matchingQualifier(kvs[i], qualifiers[i]));
            assertEquals(6, Bytes.toLong(CellUtil.cloneValue(kvs[i])));
        }
    } finally {
        HBaseTestingUtility.closeRegionAndWAL(region);
    }
    HBaseTestingUtility.closeRegionAndWAL(region);
}

