@Test
public void testMultipleTimestampRanges() throws IOException {
    // enable seek counting
    StoreFileScanner.instrument();
    region = TEST_UTIL.createTestRegion("testMultipleTimestampRanges", new HColumnDescriptor(FAMILY).setCompressionType(comprAlgo).setBloomFilterType(bloomType).setMaxVersions(3));
    // Delete the given timestamp and everything before.
    final long latestDelTS = USE_MANY_STORE_FILES ? 1397 : -1;
    createTimestampRange(1, 50, -1);
    createTimestampRange(51, 100, -1);
    if (USE_MANY_STORE_FILES) {
        createTimestampRange(100, 500, 127);
        createTimestampRange(900, 1300, -1);
        createTimestampRange(1301, 2500, latestDelTS);
        createTimestampRange(2502, 2598, -1);
        createTimestampRange(2599, 2999, -1);
    }
    prepareExpectedKVs(latestDelTS);
    for (int[] columnArr : COLUMN_SETS) {
        for (int[] rowRange : ROW_RANGES) {
            for (int maxVersions : MAX_VERSIONS_VALUES) {
                for (boolean lazySeekEnabled : new boolean[] { false, true }) {
                    testScan(columnArr, lazySeekEnabled, rowRange[0], rowRange[1], maxVersions);
                }
            }
        }
    }
    final double seekSavings = 1 - totalSeekLazy * 1.0 / totalSeekDiligent;
    System.err.println("For bloom=" + bloomType + ", compr=" + comprAlgo + " total seeks without optimization: " + totalSeekDiligent + ", with optimization: " + totalSeekLazy + " (" + String.format("%.2f%%", totalSeekLazy * 100.0 / totalSeekDiligent) + "), savings: " + String.format("%.2f%%", 100.0 * seekSavings) + "\n");
    // Test that lazy seeks are buying us something. Without the actual
    // implementation of the lazy seek optimization this will be 0.
    final double expectedSeekSavings = 0.0;
    assertTrue("Lazy seek is only saving " + String.format("%.2f%%", seekSavings * 100) + " seeks but should " + "save at least " + String.format("%.2f%%", expectedSeekSavings * 100), seekSavings >= expectedSeekSavings);
}

@Test
public void testSingleProxy() throws Throwable {
    Table table = util.getConnection().getTable(TEST_TABLE);
    Map<byte[], String> results = ping(table, null, null);
    // There are three regions so should get back three results.
    assertEquals(3, results.size());
    for (Map.Entry<byte[], String> e : results.entrySet()) {
        assertEquals("Invalid custom protocol response", "pong", e.getValue());
    }
    hello(table, "George", HELLO + "George");
    LOG.info("Did george");
    hello(table, null, "Who are you?");
    LOG.info("Who are you");
    hello(table, NOBODY, null);
    LOG.info(NOBODY);
    Map<byte[], Integer> intResults = table.coprocessorService(PingProtos.PingService.class, null, null, new Batch.Call<PingProtos.PingService, Integer>() {

        @Override
        public Integer call(PingProtos.PingService instance) throws IOException {
            BlockingRpcCallback<PingProtos.CountResponse> rpcCallback = new BlockingRpcCallback<PingProtos.CountResponse>();
            instance.count(null, PingProtos.CountRequest.newBuilder().build(), rpcCallback);
            return rpcCallback.get().getCount();
        }
    });
    int count = -1;
    for (Map.Entry<byte[], Integer> e : intResults.entrySet()) {
        assertTrue(e.getValue() > 0);
        count = e.getValue();
    }
    final int diff = 5;
    intResults = table.coprocessorService(PingProtos.PingService.class, null, null, new Batch.Call<PingProtos.PingService, Integer>() {

        @Override
        public Integer call(PingProtos.PingService instance) throws IOException {
            BlockingRpcCallback<PingProtos.IncrementCountResponse> rpcCallback = new BlockingRpcCallback<PingProtos.IncrementCountResponse>();
            instance.increment(null, PingProtos.IncrementCountRequest.newBuilder().setDiff(diff).build(), rpcCallback);
            return rpcCallback.get().getCount();
        }
    });
    // There are three regions so should get back three results.
    assertEquals(3, results.size());
    for (Map.Entry<byte[], Integer> e : intResults.entrySet()) {
        assertEquals(e.getValue().intValue(), count + diff);
    }
    table.close();
}

