@Test(timeout = 300000)
public void testMultiSlaveReplication() throws Exception {
    LOG.info("testCyclicReplication");
    MiniHBaseCluster master = utility1.startMiniCluster();
    utility2.startMiniCluster();
    utility3.startMiniCluster();
    ReplicationAdmin admin1 = new ReplicationAdmin(conf1);
    utility1.getHBaseAdmin().createTable(table);
    utility2.getHBaseAdmin().createTable(table);
    utility3.getHBaseAdmin().createTable(table);
    Table htable1 = utility1.getConnection().getTable(tableName);
    htable1.setWriteBufferSize(1024);
    Table htable2 = utility2.getConnection().getTable(tableName);
    htable2.setWriteBufferSize(1024);
    Table htable3 = utility3.getConnection().getTable(tableName);
    htable3.setWriteBufferSize(1024);
    ReplicationPeerConfig rpc = new ReplicationPeerConfig();
    rpc.setClusterKey(utility2.getClusterKey());
    admin1.addPeer("1", rpc, null);
    // put "row" and wait 'til it got around, then delete
    putAndWait(row, famName, htable1, htable2);
    deleteAndWait(row, htable1, htable2);
    // check it wasn't replication to cluster 3
    checkRow(row, 0, htable3);
    putAndWait(row2, famName, htable1, htable2);
    // now roll the region server's logs
    rollWALAndWait(utility1, htable1.getName(), row2);
    // after the log was rolled put a new row
    putAndWait(row3, famName, htable1, htable2);
    rpc = new ReplicationPeerConfig();
    rpc.setClusterKey(utility3.getClusterKey());
    admin1.addPeer("2", rpc, null);
    // put a row, check it was replicated to all clusters
    putAndWait(row1, famName, htable1, htable2, htable3);
    // delete and verify
    deleteAndWait(row1, htable1, htable2, htable3);
    // make sure row2 did not get replicated after
    // cluster 3 was added
    checkRow(row2, 0, htable3);
    // row3 will get replicated, because it was in the
    // latest log
    checkRow(row3, 1, htable3);
    Put p = new Put(row);
    p.addColumn(famName, row, row);
    htable1.put(p);
    // now roll the logs again
    rollWALAndWait(utility1, htable1.getName(), row);
    // cleanup "row2", also conveniently use this to wait replication
    // to finish
    deleteAndWait(row2, htable1, htable2, htable3);
    // Even if the log was rolled in the middle of the replication
    // "row" is still replication.
    checkRow(row, 1, htable2);
    // Replication thread of cluster 2 may be sleeping, and since row2 is not there in it,
    // we should wait before checking.
    checkWithWait(row, 1, htable3);
    // cleanup the rest
    deleteAndWait(row, htable1, htable2, htable3);
    deleteAndWait(row3, htable1, htable2, htable3);
    utility3.shutdownMiniCluster();
    utility2.shutdownMiniCluster();
    utility1.shutdownMiniCluster();
}

@Test
public void testParseTableCFsFromConfig() {
    Map<TableName, List<String>> tabCFsMap = null;
    // 1. null or empty string, result should be null
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig(null);
    assertEquals(null, tabCFsMap);
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("");
    assertEquals(null, tabCFsMap);
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("   ");
    assertEquals(null, tabCFsMap);
    TableName tab1 = TableName.valueOf("tab1");
    TableName tab2 = TableName.valueOf("tab2");
    TableName tab3 = TableName.valueOf("tab3");
    // 2. single table: "tab1" / "tab2:cf1" / "tab3:cf1,cf3"
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("tab1");
    // only one table
    assertEquals(1, tabCFsMap.size());
    // its table name is "tab1"
    assertTrue(tabCFsMap.containsKey(tab1));
    // not other table
    assertFalse(tabCFsMap.containsKey(tab2));
    // null cf-list,
    assertEquals(null, tabCFsMap.get(tab1));
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("tab2:cf1");
    // only one table
    assertEquals(1, tabCFsMap.size());
    // its table name is "tab2"
    assertTrue(tabCFsMap.containsKey(tab2));
    // not other table
    assertFalse(tabCFsMap.containsKey(tab1));
    // cf-list contains only 1 cf
    assertEquals(1, tabCFsMap.get(tab2).size());
    // the only cf is "cf1"
    assertEquals("cf1", tabCFsMap.get(tab2).get(0));
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("tab3 : cf1 , cf3");
    // only one table
    assertEquals(1, tabCFsMap.size());
    // its table name is "tab2"
    assertTrue(tabCFsMap.containsKey(tab3));
    // not other table
    assertFalse(tabCFsMap.containsKey(tab1));
    // cf-list contains 2 cf
    assertEquals(2, tabCFsMap.get(tab3).size());
    // contains "cf1"
    assertTrue(tabCFsMap.get(tab3).contains("cf1"));
    // contains "cf3"
    assertTrue(tabCFsMap.get(tab3).contains("cf3"));
    // 3. multiple tables: "tab1 ; tab2:cf1 ; tab3:cf1,cf3"
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("tab1 ; tab2:cf1 ; tab3:cf1,cf3");
    // 3.1 contains 3 tables : "tab1", "tab2" and "tab3"
    assertEquals(3, tabCFsMap.size());
    assertTrue(tabCFsMap.containsKey(tab1));
    assertTrue(tabCFsMap.containsKey(tab2));
    assertTrue(tabCFsMap.containsKey(tab3));
    // 3.2 table "tab1" : null cf-list
    assertEquals(null, tabCFsMap.get(tab1));
    // 3.3 table "tab2" : cf-list contains a single cf "cf1"
    assertEquals(1, tabCFsMap.get(tab2).size());
    assertEquals("cf1", tabCFsMap.get(tab2).get(0));
    // 3.4 table "tab3" : cf-list contains "cf1" and "cf3"
    assertEquals(2, tabCFsMap.get(tab3).size());
    assertTrue(tabCFsMap.get(tab3).contains("cf1"));
    assertTrue(tabCFsMap.get(tab3).contains("cf3"));
    // 4. contiguous or additional ";"(table delimiter) or ","(cf delimiter) can be tolerated
    // still use the example of multiple tables: "tab1 ; tab2:cf1 ; tab3:cf1,cf3"
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("tab1 ; ; tab2:cf1 ; tab3:cf1,,cf3 ;");
    // 4.1 contains 3 tables : "tab1", "tab2" and "tab3"
    assertEquals(3, tabCFsMap.size());
    assertTrue(tabCFsMap.containsKey(tab1));
    assertTrue(tabCFsMap.containsKey(tab2));
    assertTrue(tabCFsMap.containsKey(tab3));
    // 4.2 table "tab1" : null cf-list
    assertEquals(null, tabCFsMap.get(tab1));
    // 4.3 table "tab2" : cf-list contains a single cf "cf1"
    assertEquals(1, tabCFsMap.get(tab2).size());
    assertEquals("cf1", tabCFsMap.get(tab2).get(0));
    // 4.4 table "tab3" : cf-list contains "cf1" and "cf3"
    assertEquals(2, tabCFsMap.get(tab3).size());
    assertTrue(tabCFsMap.get(tab3).contains("cf1"));
    assertTrue(tabCFsMap.get(tab3).contains("cf3"));
    // 5. invalid format "tab1:tt:cf1 ; tab2::cf1 ; tab3:cf1,cf3"
    //    "tab1:tt:cf1" and "tab2::cf1" are invalid and will be ignored totally
    tabCFsMap = ReplicationSerDeHelper.parseTableCFsFromConfig("tab1:tt:cf1 ; tab2::cf1 ; tab3:cf1,cf3");
    // 5.1 no "tab1" and "tab2", only "tab3"
    // only one table
    assertEquals(1, tabCFsMap.size());
    assertFalse(tabCFsMap.containsKey(tab1));
    assertFalse(tabCFsMap.containsKey(tab2));
    assertTrue(tabCFsMap.containsKey(tab3));
    // 5.2 table "tab3" : cf-list contains "cf1" and "cf3"
    assertEquals(2, tabCFsMap.get(tab3).size());
    assertTrue(tabCFsMap.get(tab3).contains("cf1"));
    assertTrue(tabCFsMap.get(tab3).contains("cf3"));
}

