        deleteAndWaitWithFamily(row1, f2Name, htab1C, htab2C);
        putAndWaitWithFamily(row1, f3Name, htab1C, htab2C);
        ensureRowNotReplicated(row1, f3Name, htab3C);
        deleteAndWaitWithFamily(row1, f3Name, htab1C, htab2C);
