    edit.add(new KeyValue(rowName, famName, qualifier, now, value));
    WALKey walKey = new WALKey(hri.getEncodedNameAsBytes(), tableName, now, mvcc, scopes);
    wal.append(hri, walKey, edit, true);
    wal.sync();
    Get get = new Get(rowName);
