@Test
public void testNegativeCases() throws Exception {
    executeNegativeCase("(");
    executeNegativeCase(")");
    executeNegativeCase("()");
    executeNegativeCase("(a");
    executeNegativeCase("a&");
    executeNegativeCase("a&|b");
    executeNegativeCase("!");
    executeNegativeCase("a!");
    executeNegativeCase("a!&");
    executeNegativeCase("&");
    executeNegativeCase("|");
    executeNegativeCase("!(a|(b&c)&!b");
    executeNegativeCase("!!a");
    executeNegativeCase("( a & b ) | ( c & d e)");
    executeNegativeCase("! a");
}

