@Test
public void testSizeCalculation() {
    TestOptions opts = new PerformanceEvaluation.TestOptions();
    opts = PerformanceEvaluation.calculateRowsAndSize(opts);
    int rows = opts.getPerClientRunRows();
    // Default row count
    final int defaultPerClientRunRows = 1024 * 1024;
    assertEquals(defaultPerClientRunRows, rows);
    // If size is 2G, then twice the row count.
    opts.setSize(2.0f);
    opts = PerformanceEvaluation.calculateRowsAndSize(opts);
    assertEquals(defaultPerClientRunRows * 2, opts.getPerClientRunRows());
    // If two clients, then they get half the rows each.
    opts.setNumClientThreads(2);
    opts = PerformanceEvaluation.calculateRowsAndSize(opts);
    assertEquals(defaultPerClientRunRows, opts.getPerClientRunRows());
    // What if valueSize is 'random'? Then half of the valueSize so twice the rows.
    opts.valueRandom = true;
    opts = PerformanceEvaluation.calculateRowsAndSize(opts);
    assertEquals(defaultPerClientRunRows * 2, opts.getPerClientRunRows());
}

@Test
public void testZipfian() throws NoSuchMethodException, SecurityException, InstantiationException, IllegalAccessException, IllegalArgumentException, InvocationTargetException {
    TestOptions opts = new PerformanceEvaluation.TestOptions();
    opts.setValueZipf(true);
    final int valueSize = 1024;
    opts.setValueSize(valueSize);
    RandomReadTest rrt = new RandomReadTest(null, opts, null);
    Constructor<?> ctor = Histogram.class.getDeclaredConstructor(com.codahale.metrics.Reservoir.class);
    ctor.setAccessible(true);
    Histogram histogram = (Histogram) ctor.newInstance(new UniformReservoir(1024 * 500));
    for (int i = 0; i < 100; i++) {
        histogram.update(rrt.getValueLength(null));
    }
    Snapshot snapshot = histogram.getSnapshot();
    double stddev = snapshot.getStdDev();
    assertTrue(stddev != 0 && stddev != 1.0);
    assertTrue(snapshot.getStdDev() != 0);
    double median = snapshot.getMedian();
    assertTrue(median != 0 && median != 1 && median != valueSize);
}

/**
 * For HBASE-71. Try a few different configurations of starting and stopping
 * region servers to see if the assignment or regions is pretty balanced.
 * @throws IOException
 * @throws InterruptedException
 */
@Test(timeout = 300000)
public void testRebalanceOnRegionServerNumberChange() throws IOException, InterruptedException {
    try (Connection connection = ConnectionFactory.createConnection(UTIL.getConfiguration());
        Admin admin = connection.getAdmin()) {
        admin.createTable(this.desc, Arrays.copyOfRange(HBaseTestingUtility.KEYS, 1, HBaseTestingUtility.KEYS.length));
        this.regionLocator = connection.getRegionLocator(this.desc.getTableName());
        MetaTableAccessor.fullScanMetaAndPrint(admin.getConnection());
        assertEquals("Test table should have right number of regions", HBaseTestingUtility.KEYS.length, this.regionLocator.getStartKeys().length);
        // verify that the region assignments are balanced to start out
        assertRegionsAreBalanced();
        // add a region server - total of 2
        LOG.info("Started second server=" + UTIL.getHBaseCluster().startRegionServer().getRegionServer().getServerName());
        UTIL.getHBaseCluster().getMaster().balance();
        assertRegionsAreBalanced();
        // On a balanced cluster, calling balance() should return true
        assert (UTIL.getHBaseCluster().getMaster().balance() == true);
        // if we add a server, then the balance() call should return true
        // add a region server - total of 3
        LOG.info("Started third server=" + UTIL.getHBaseCluster().startRegionServer().getRegionServer().getServerName());
        assert (UTIL.getHBaseCluster().getMaster().balance() == true);
        assertRegionsAreBalanced();
        // kill a region server - total of 2
        LOG.info("Stopped third server=" + UTIL.getHBaseCluster().stopRegionServer(2, false));
        UTIL.getHBaseCluster().waitOnRegionServer(2);
        waitOnCrashProcessing();
        UTIL.getHBaseCluster().getMaster().balance();
        assertRegionsAreBalanced();
        // start two more region servers - total of 4
        LOG.info("Readding third server=" + UTIL.getHBaseCluster().startRegionServer().getRegionServer().getServerName());
        LOG.info("Added fourth server=" + UTIL.getHBaseCluster().startRegionServer().getRegionServer().getServerName());
        waitOnCrashProcessing();
        assert (UTIL.getHBaseCluster().getMaster().balance() == true);
        assertRegionsAreBalanced();
        for (int i = 0; i < 6; i++) {
            LOG.info("Adding " + (i + 5) + "th region server");
            UTIL.getHBaseCluster().startRegionServer();
        }
        assert (UTIL.getHBaseCluster().getMaster().balance() == true);
        assertRegionsAreBalanced();
        regionLocator.close();
    }
}

