@Test
public void testCreateKeyValueInvalidNegativeLength() {
    KeyValue kv_0 = new // 51 bytes
    KeyValue(// 51 bytes
    Bytes.toBytes("myRow"), // 51 bytes
    Bytes.toBytes("myCF"), Bytes.toBytes("myQualifier"), 12345L, Bytes.toBytes("my12345"));
    KeyValue kv_1 = new // 49 bytes
    KeyValue(// 49 bytes
    Bytes.toBytes("myRow"), // 49 bytes
    Bytes.toBytes("myCF"), Bytes.toBytes("myQualifier"), 12345L, Bytes.toBytes("my123"));
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    DataOutputStream dos = new DataOutputStream(baos);
    long l = 0;
    try {
        l = KeyValue.oswrite(kv_0, dos, false);
        l += KeyValue.oswrite(kv_1, dos, false);
        assertEquals(100L, l);
    } catch (IOException e) {
        fail("Unexpected IOException" + e.getMessage());
    }
    ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
    DataInputStream dis = new DataInputStream(bais);
    try {
        KeyValueUtil.create(dis);
        assertTrue(kv_0.equals(kv_1));
    } catch (Exception e) {
        fail("Unexpected Exception" + e.getMessage());
    }
    // length -1
    try {
        // even if we have a good kv now in dis we will just pass length with -1 for simplicity
        KeyValueUtil.create(-1, dis);
        fail("Expected corrupt stream");
    } catch (Exception e) {
        assertEquals("Failed read -1 bytes, stream corrupt?", e.getMessage());
    }
}

