@Test
public void testPrepend() throws Exception {
    // Push
    for (int i = 1; i <= CAPACITY; ++i) {
        assertTrue(queue.offer(new TestObject(CAPACITY - i, i)));
        assertEquals(i, queue.size());
        assertEquals(CAPACITY - i, queue.remainingCapacity());
    }
    // Pop
    for (int i = 1; i <= CAPACITY; ++i) {
