@Test(timeout = 180000)
public void testCheckTableLocks() throws Exception {
    IncrementingEnvironmentEdge edge = new IncrementingEnvironmentEdge(0);
    EnvironmentEdgeManager.injectEdge(edge);
    // check no errors
    HBaseFsck hbck = doFsck(conf, false);
    assertNoErrors(hbck);
    ServerName mockName = ServerName.valueOf("localhost", 60000, 1);
    final TableName tableName = TableName.valueOf("foo");
    // obtain one lock
    final TableLockManager tableLockManager = TableLockManager.createTableLockManager(conf, TEST_UTIL.getZooKeeperWatcher(), mockName);
    TableLockManager.TableLock writeLock = tableLockManager.writeLock(tableName, "testCheckTableLocks");
    writeLock.acquire();
    hbck = doFsck(conf, false);
    // should not have expired, no problems
    assertNoErrors(hbck);
    edge.incrementTime(conf.getLong(TableLockManager.TABLE_LOCK_EXPIRE_TIMEOUT, // let table lock expire
    TableLockManager.DEFAULT_TABLE_LOCK_EXPIRE_TIMEOUT_MS));
    hbck = doFsck(conf, false);
    assertErrors(hbck, new HBaseFsck.ErrorReporter.ERROR_CODE[] { HBaseFsck.ErrorReporter.ERROR_CODE.EXPIRED_TABLE_LOCK });
    final CountDownLatch latch = new CountDownLatch(1);
    new Thread() {

        @Override
        public void run() {
            TableLockManager.TableLock readLock = tableLockManager.writeLock(tableName, "testCheckTableLocks");
            try {
                latch.countDown();
                readLock.acquire();
            } catch (IOException ex) {
                fail();
            } catch (IllegalStateException ex) {
                // expected, since this will be reaped under us.
                return;
            }
            fail("should not have come here");
        }
    }.start();
    // wait until thread starts
    latch.await();
    // wait some more to ensure writeLock.acquire() is called
    Threads.sleep(300);
    hbck = doFsck(conf, false);
    // still one expired, one not-expired
    assertErrors(hbck, new HBaseFsck.ErrorReporter.ERROR_CODE[] { HBaseFsck.ErrorReporter.ERROR_CODE.EXPIRED_TABLE_LOCK });
    edge.incrementTime(conf.getLong(TableLockManager.TABLE_LOCK_EXPIRE_TIMEOUT, // let table lock expire
    TableLockManager.DEFAULT_TABLE_LOCK_EXPIRE_TIMEOUT_MS));
    hbck = doFsck(conf, false);
    assertErrors(hbck, new HBaseFsck.ErrorReporter.ERROR_CODE[] { HBaseFsck.ErrorReporter.ERROR_CODE.EXPIRED_TABLE_LOCK, // both are expired
    HBaseFsck.ErrorReporter.ERROR_CODE.EXPIRED_TABLE_LOCK });
    Configuration localConf = new Configuration(conf);
    // reaping from ZKInterProcessWriteLock uses znode cTime,
    // which is not injectable through EnvironmentEdge
    localConf.setLong(TableLockManager.TABLE_LOCK_EXPIRE_TIMEOUT, 1);
    Threads.sleep(10);
    // now fix both cases
    hbck = doFsck(localConf, true);
    hbck = doFsck(localConf, false);
    assertNoErrors(hbck);
    // ensure that locks are deleted
    writeLock = tableLockManager.writeLock(tableName, "should acquire without blocking");
    // this should not block.
    writeLock.acquire();
    // release for clean state
    writeLock.release();
    tableLockManager.tableDeleted(tableName);
}

