@Test
public void testIteratorIsolation() throws Exception {
    SortedCopyOnWriteSet<String> set = new SortedCopyOnWriteSet<String>(Lists.newArrayList("a", "b", "c", "d", "e"));
    // isolation of remove()
    Iterator<String> iter = set.iterator();
    set.remove("c");
    boolean found = false;
    while (iter.hasNext() && !found) {
        found = "c".equals(iter.next());
    }
    assertTrue(found);
    iter = set.iterator();
    found = false;
    while (iter.hasNext() && !found) {
        found = "c".equals(iter.next());
    }
    assertFalse(found);
    // isolation of add()
    iter = set.iterator();
    set.add("f");
    found = false;
    while (iter.hasNext() && !found) {
        String next = iter.next();
        found = "f".equals(next);
    }
    assertFalse(found);
    // isolation of addAll()
    iter = set.iterator();
    set.addAll(Lists.newArrayList("g", "h", "i"));
    found = false;
    while (iter.hasNext() && !found) {
        String next = iter.next();
        found = "g".equals(next) || "h".equals(next) || "i".equals(next);
    }
    assertFalse(found);
    // isolation of clear()
    iter = set.iterator();
    set.clear();
    assertEquals(0, set.size());
    int size = 0;
    while (iter.hasNext()) {
        iter.next();
        size++;
    }
    assertTrue(size > 0);
}

@Test
public void testSorting() throws Exception {
    SortedList<String> list = new SortedList<String>(new StringComparator());
    list.add("c");
