@Test
public void testIteratorIsolation() throws Exception {
    SortedList<String> list = new SortedList<String>(Lists.newArrayList("a", "b", "c", "d", "e"), new StringComparator());
    // isolation of remove()
    Iterator<String> iter = list.iterator();
    list.remove("c");
    boolean found = false;
    while (iter.hasNext() && !found) {
        found = "c".equals(iter.next());
    }
    assertTrue(found);
    iter = list.iterator();
    found = false;
    while (iter.hasNext() && !found) {
        found = "c".equals(iter.next());
    }
    assertFalse(found);
    // isolation of add()
    iter = list.iterator();
    list.add("f");
    found = false;
    while (iter.hasNext() && !found) {
        String next = iter.next();
        found = "f".equals(next);
    }
    assertFalse(found);
    // isolation of addAll()
    iter = list.iterator();
    list.addAll(Lists.newArrayList("g", "h", "i"));
    found = false;
    while (iter.hasNext() && !found) {
        String next = iter.next();
        found = "g".equals(next) || "h".equals(next) || "i".equals(next);
    }
    assertFalse(found);
    // isolation of clear()
    iter = list.iterator();
    list.clear();
    assertEquals(0, list.size());
    int size = 0;
    while (iter.hasNext()) {
        iter.next();
        size++;
    }
    assertTrue(size > 0);
}

