@Test(timeout = 300000)
public void testConcurrentSplitLogAndReplayRecoverEdit() throws IOException {
    LOG.info("testConcurrentSplitLogAndReplayRecoverEdit");
    // Generate wals for our destination region
    String regionName = "r0";
    final Path regiondir = new Path(TABLEDIR, regionName);
    REGIONS.clear();
    REGIONS.add(regionName);
    generateWALs(-1);
    wals.getWAL(Bytes.toBytes(regionName), null);
    FileStatus[] logfiles = fs.listStatus(WALDIR);
    assertTrue("There should be some log file", logfiles != null && logfiles.length > 0);
    WALSplitter logSplitter = new WALSplitter(wals, conf, HBASEDIR, fs, null, null, this.mode) {

        @Override
        protected Writer createWriter(Path logfile) throws IOException {
            Writer writer = wals.createRecoveredEditsWriter(this.fs, logfile);
            // After creating writer, simulate region's
            // replayRecoveredEditsIfAny() which gets SplitEditFiles of this
            // region and delete them, excluding files with '.temp' suffix.
            NavigableSet<Path> files = WALSplitter.getSplitEditFilesSorted(fs, regiondir);
            if (files != null && !files.isEmpty()) {
                for (Path file : files) {
                    if (!this.fs.delete(file, false)) {
                        LOG.error("Failed delete of " + file);
                    } else {
                        LOG.debug("Deleted recovered.edits file=" + file);
                    }
                }
            }
            return writer;
        }
    };
    try {
        logSplitter.splitLogFile(logfiles[0], null);
    } catch (IOException e) {
        LOG.info(e);
        fail("Throws IOException when spliting " + "log, it is most likely because writing file does not " + "exist which is caused by concurrent replayRecoveredEditsIfAny()");
    }
    if (fs.exists(CORRUPTDIR)) {
        if (fs.listStatus(CORRUPTDIR).length > 0) {
            fail("There are some corrupt logs, " + "it is most likely caused by concurrent replayRecoveredEditsIfAny()");
        }
    }
}

@Test(timeout = 30000)
public void testWriteLockExcludesWriters() throws Exception {
    final String testName = "testWriteLockExcludesWriters";
    final ZKInterProcessReadWriteLock readWriteLock = getReadWriteLock(testName);
    List<Future<Void>> results = Lists.newArrayList();
    for (int i = 0; i < NUM_THREADS; ++i) {
        final String threadDesc = testName + i;
        results.add(executor.submit(new Callable<Void>() {

            @Override
            public Void call() throws IOException {
                ZKInterProcessWriteLock writeLock = readWriteLock.writeLock(Bytes.toBytes(threadDesc));
                try {
                    writeLock.acquire();
                    try {
                        // No one else should hold the lock
                        assertTrue(isLockHeld.compareAndSet(false, true));
                        Thread.sleep(1000);
                        // No one else should have released the lock
                        assertTrue(isLockHeld.compareAndSet(true, false));
                    } finally {
                        isLockHeld.set(false);
                        writeLock.release();
                    }
                } catch (InterruptedException e) {
                    LOG.warn(threadDesc + " interrupted", e);
                    Thread.currentThread().interrupt();
                    throw new InterruptedIOException();
                }
                return null;
            }
        }));
    }
    MultithreadedTestUtil.assertOnFutures(results);
}

@Test(timeout = 30000)
public void testReadLockDoesNotExcludeReaders() throws Exception {
    final String testName = "testReadLockDoesNotExcludeReaders";
    final ZKInterProcessReadWriteLock readWriteLock = getReadWriteLock(testName);
    final CountDownLatch locksAcquiredLatch = new CountDownLatch(NUM_THREADS);
    final AtomicInteger locksHeld = new AtomicInteger(0);
    List<Future<Void>> results = Lists.newArrayList();
    for (int i = 0; i < NUM_THREADS; ++i) {
        final String threadDesc = testName + i;
        results.add(executor.submit(new Callable<Void>() {

            @Override
            public Void call() throws Exception {
                ZKInterProcessReadLock readLock = readWriteLock.readLock(Bytes.toBytes(threadDesc));
                readLock.acquire();
                try {
                    locksHeld.incrementAndGet();
                    locksAcquiredLatch.countDown();
                    Thread.sleep(1000);
                } finally {
                    readLock.release();
                    locksHeld.decrementAndGet();
                }
                return null;
            }
        }));
    }
    locksAcquiredLatch.await();
    assertEquals(locksHeld.get(), NUM_THREADS);
    MultithreadedTestUtil.assertOnFutures(results);
}

@Test(timeout = 30000)
public void testReadLockExcludesWriters() throws Exception {
    // Submit a read lock request first
    // Submit a write lock request second
    final String testName = "testReadLockExcludesWriters";
    List<Future<Void>> results = Lists.newArrayList();
    final CountDownLatch readLockAcquiredLatch = new CountDownLatch(1);
    Callable<Void> acquireReadLock = new Callable<Void>() {

        @Override
        public Void call() throws Exception {
            final String threadDesc = testName + "-acquireReadLock";
            ZKInterProcessReadLock readLock = getReadWriteLock(testName).readLock(Bytes.toBytes(threadDesc));
            readLock.acquire();
            try {
                assertTrue(isLockHeld.compareAndSet(false, true));
                readLockAcquiredLatch.countDown();
                Thread.sleep(1000);
            } finally {
                isLockHeld.set(false);
                readLock.release();
            }
            return null;
        }
    };
    Callable<Void> acquireWriteLock = new Callable<Void>() {

        @Override
        public Void call() throws Exception {
            final String threadDesc = testName + "-acquireWriteLock";
            ZKInterProcessWriteLock writeLock = getReadWriteLock(testName).writeLock(Bytes.toBytes(threadDesc));
            readLockAcquiredLatch.await();
            assertTrue(isLockHeld.get());
            writeLock.acquire();
            try {
                assertFalse(isLockHeld.get());
            } finally {
                writeLock.release();
            }
            return null;
        }
    };
    results.add(executor.submit(acquireReadLock));
    results.add(executor.submit(acquireWriteLock));
    MultithreadedTestUtil.assertOnFutures(results);
}

